function deployRentalSafe(
    address[] calldata owners,
    uint256 threshold
) external returns (address safe) {
    // Require that the threshold is valid.
    if (threshold == 0 || threshold > owners.length) {
        revert Errors.FactoryPolicy_InvalidSafeThreshold(threshold, owners.length);
    }

    // Delegate call from the safe so that the rental manager module can be enabled
    // right after the safe is deployed.
    bytes memory data = abi.encodeCall(
        Factory.initializeRentalSafe,
        (address(stopPolicy), address(guardPolicy))
    );

    // Create gnosis initializer payload.
    bytes memory initializerPayload = abi.encodeCall(
        ISafe.setup,
        (
            // owners array.
            owners,
            // number of signatures needed to execute transactions.
            threshold,
            // Address to direct the payload to.
            address(this),
            // Encoded call to execute.
            data,
            // Fallback manager address.
            address(fallbackHandler),
            // Payment token.
            address(0),
            // Payment amount.
            0,
            // Payment receiver
            payable(address(0))
        )
    );

    // Deploy a safe proxy using initializer values for the Safe.setup() call
    // with a salt nonce that is unique to each chain to guarantee cross-chain
    // unique safe addresses.
    safe = address(
        safeProxyFactory.createProxyWithNonce(
            address(safeSingleton),
            initializerPayload,
            uint256(keccak256(abi.encode(STORE.totalSafes() + 1, block.chainid)))
        )
    );

    // Store the deployed safe.
    STORE.addRentalSafe(safe);

    // Emit the event.
    emit Events.RentalSafeDeployment(safe, owners, threshold);
}

function _checkTransaction(address from, address to, bytes memory data) private view {
    bytes4 selector;

    // Load in the function selector.
    assembly {
        selector := mload(add(data, 0x20))
    }

    if (selector == e721_safe_transfer_from_1_selector) {
        // Load the token ID from calldata.
        uint256 tokenId = uint256(
            _loadValueFromCalldata(data, e721_safe_transfer_from_1_token_id_offset)
        );

        // Check if the selector is allowed.
        _revertSelectorOnActiveRental(selector, from, to, tokenId);
    } else if (selector == e721_safe_transfer_from_2_selector) {
        // Load the token ID from calldata.
        uint256 tokenId = uint256(
            _loadValueFromCalldata(data, e721_safe_transfer_from_2_token_id_offset)
        );

        // Check if the selector is allowed.
        _revertSelectorOnActiveRental(selector, from, to, tokenId);
    } else if (selector == e721_transfer_from_selector) {
        // Load the token ID from calldata.
        uint256 tokenId = uint256(
            _loadValueFromCalldata(data, e721_transfer_from_token_id_offset)
        );

        // Check if the selector is allowed.
        _revertSelectorOnActiveRental(selector, from, to, tokenId);
    } else if (selector == e721_approve_selector) {
        // Load the token ID from calldata.
        uint256 tokenId = uint256(
            _loadValueFromCalldata(data, e721_approve_token_id_offset)
        );

        // Check if the selector is allowed.
        _revertSelectorOnActiveRental(selector, from, to, tokenId);
    } else if (selector == e1155_safe_transfer_from_selector) {
        // Load the token ID from calldata.
        uint256 tokenId = uint256(
            _loadValueFromCalldata(data, e1155_safe_transfer_from_token_id_offset)
        );

        // Check if the selector is allowed.
        _revertSelectorOnActiveRental(selector, from, to, tokenId);
    } else if (selector == gnosis_safe_enable_module_selector) {
        // Load the extension address from calldata.
        address extension = address(
