+        // Get the nonce
+        uint256 tokenIdNonce = tokenIdNonces[tokenId];
+
+        // Increment it
+        tokenIdNonces[tokenId] += 1;
+
+        // Return the old nonce
+        return tokenIdNonce;
+    }
+
+    function _isContract(address account) internal view returns (bool) {
+        uint256 size;
+        assembly {
+            size := extcodesize(account)
+        }
+        return size > 0;
+    }
+
