function onOFTReceived(
    uint16 _srcChainId,
    bytes calldata,
    uint64,
    bytes32,
    uint _amount,
    bytes memory _payload
) external override onlyLzApp {
    (uint8 msgType, address _from, address _to, bool deliverEth) = abi
        .decode(_payload, (uint8, address, address, bool));

