        ensureContract(target_);
        _migrateKernel(Kernel(target_));
    } else if (action_ == Actions.ChangeExecutor) {
        executor = target_;
    } else if (action_ == Actions.ChangeAdmin) {
        admin = target_;
    }

    emit Events.ActionExecuted(action_, target_);
}

