        postBridge.swapPayload,
        (SwapParams)
    );

    if (!gasIsEth) {
        IERC20(bridgeToken).transferFrom(
            msg.sender,
            address(this),
            amt2Bridge
        );
        IERC20(bridgeToken).approve(address(router), amt2Bridge);
    }

